function extractPropsInterface(node: ts.FunctionDeclaration): string | null {
  if (!node.parameters || node.parameters.length === 0) return null
  const firstParam = node.parameters[0]
  if (firstParam.type) {
    const typeText = firstParam.type.getText()
    return typeText || null
